import{z as d,x as E,o as e,c as p,q as l,j as r,D as t,d as s,s as h,S as i,b as o}from"./chunks/framework.C8m1ZpeB.js";const v=JSON.parse('{"title":"Johnson 全源","description":"","frontmatter":{"title":"Johnson 全源","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/johnson-apsp.md","filePath":"cs/johnson-apsp.md","lastUpdated":1791063341000}'),B={name:"cs/johnson-apsp.md"};function u(A,a,m,f,F,D){const n=E("Mermaid");return e(),p("div",null,[a[2]||(a[2]=l('<h1 id="johnson-全源" tabindex="-1">Johnson 全源 <a class="header-anchor" href="#johnson-全源" aria-label="Permalink to &quot;Johnson 全源&quot;">​</a></h1><div class="epigraph"><p>先用一次 Bellman–Ford 给每个点势，把边权改写成非负；再从每个源跑 Dijkstra，得到一般权图上的稀疏全源。</p><footer>—— 据 Johnson, Efficient Algorithms for Shortest Paths in Sparse Networks, 1977；CLRS 第 25.3 节整理</footer></div><p>上一课<a href="/cs/floyd-warshall">Floyd–Warshall</a>用中间点 DP 在 \\(\\Theta(V^3)\\) 内做全源，并声明稀疏非负更宜 \\(V\\) 次 Dijkstra、一般权不要对负边跑 Dijkstra。本课不重写三重循环。缺口是<strong>重新赋权</strong>：势函数 \\(h(v)=\\delta(s&#39;,v)\\) 使 \\(w&#39;(u,v)=w(u,v)+h(u)-h(v)\\ge 0\\)，最短路的顶点序列不变。有负边、无负环的稀疏图因此回到堆 Dijkstra。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(V\\) 次 Bellman–Ford 是 \\(O(V^2 E)\\)，稠密时比 Floyd 差，稀疏时仍厚。Johnson：加超源 \\(s&#39;\\) 向所有点连 \\(0\\) 边，Bellman–Ford 一次得 \\(h\\)，检测负环。新权 \\(w&#39;\\) 非负，且对任意路径 \\(p\\)，\\(w&#39;(p)=w(p)+h(\\mathrm{start})-h(\\mathrm{end})\\)，故同一 \\(u,v\\) 之间最短路在 \\(w\\) 与 \\(w&#39;\\) 下是同一条。对每个 \\(u\\) 跑 Dijkstra（\\(w&#39;\\)），再还原 \\(w\\) 的距离。二叉堆下 \\(O(VE\\log V)\\) 量级，稀疏时优于 \\(V^3\\)。</p><p><span class="marginnote">数字实例：边 u→v 权 −3，若算得 h(u)=0、h(v)=−3，则 w′=−3+0−(−3)=0；负边被抬成非负，而路径两端各加各减，中间项全部相消。</span></p><p>缺口是势，不是再发明全源 DP。势来自<a href="/cs/diff-constraint">差分约束</a>同一三角不等式：\\(h(v)\\le h(u)+w(u,v)\\) 当 \\(h=\\delta(s&#39;,\\cdot)\\)。</p><h3 id="重新赋权不是改图的可达性" tabindex="-1">重新赋权不是改图的可达性 <a class="header-anchor" href="#重新赋权不是改图的可达性" aria-label="Permalink to &quot;重新赋权不是改图的可达性&quot;">​</a></h3><p>\\(w&#39;\\) 可以让边的数值变大，但 \\(w&#39;(u,v)=0\\) 不表示原图有零权。负环仍先被超源那一次 BF 抓住；有负环则算法拒绝，与 Floyd 对角负值同一语义。</p><p><span class="marginnote">Johnson 1977。CLRS 25.3。势 \\(h\\) 不必是最短路：任意使 \\(w&#39;\\) 非负的势都保持最短路集合；超源 BF 是一份可计算的势。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建 \\(s&#39;\\)。BF：失败则负环。成功则算 \\(w&#39;\\)。对每个 \\(u\\)：Dijkstra 得 \\(\\delta&#39;(u,\\cdot)\\)，令 \\(\\delta(u,v)=\\delta&#39;(u,v)-h(u)+h(v)\\)。不可达保持 \\(\\infty\\)。</p>',12)),(e(),r(i,null,{default:t(()=>[h(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E4%B8%80%E8%88%AC%E6%9D%83%E3%80%81%E6%97%A0%E8%B4%9F%E7%8E%AF%22%5D%20--%3E%20H%5B%22%E8%B6%85%E6%BA%90%20BF%20%E5%BE%97%E5%8A%BF%20h%22%5D%0A%20%20H%20--%3E%20WP%5B%22w'%20%E2%89%A5%200%22%5D%0A%20%20WP%20--%3E%20D%5B%22V%20%E6%AC%A1%20Dijkstra%22%5D%0A%20%20D%20--%3E%20DEL%5B%22%E8%BF%98%E5%8E%9F%20%CE%B4%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("p",null,[s("实现用"),o("a",{href:"/cs/dijkstra-heap"},"Dial 与堆变体"),s("里选定的队列。稠密图直接 Floyd 更干净，不必 Johnson。")],-1)),a[4]||(a[4]=o("h2",{id:"机制",tabindex:"-1"},[s("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=o("p",null,"路径上中间 \\(h\\) 消掉，只剩端点，故比较 \\(w'\\) 最短即比较 \\(w\\) 最短。不要在原负权图上对每个源 Dijkstra。也不要把势当成启发式 \\(A^*\\) 的 \\(h\\)：这里的 \\(h\\) 来自超源，保证非负，不是到汇的估计。",-1)),a[6]||(a[6]=o("p",null,[o("span",{class:"marginnote"},"常见误区：初学者容易以为「重新赋权改了图，答案也会变」。实际上每条 u→v 路径都被加上同一个常数 h(u)−h(v)，所有候选同加同减，排序不变，最短路集合原样保留。")],-1)),a[7]||(a[7]=o("p",null,"一条路径上势如何「中间相消、只留端点」：",-1)),(e(),r(i,null,{default:t(()=>[h(n,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20LR%0A%20%20U%5B%22u%EF%BC%9A%E7%B4%AF%E7%A7%AF%20%2Bh(u)%22%5D%20--%3E%7C%22w(u%2Cx)%2Bh(u)%E2%88%92h(x)%22%7C%20X%5B%22x%EF%BC%9A%E2%88%92h(x)%2Bh(x)%EF%BC%8C%E6%8A%B5%E6%B6%88%22%5D%0A%20%20X%20--%3E%7C%22w(x%2Cy)%2Bh(x)%E2%88%92h(y)%22%7C%20Y%5B%22y%EF%BC%9A%E2%88%92h(y)%2Bh(y)%EF%BC%8C%E6%8A%B5%E6%B6%88%22%5D%0A%20%20Y%20--%3E%7C%22w(y%2Cv)%2Bh(y)%E2%88%92h(v)%22%7C%20V%5B%22v%EF%BC%9A%E7%B4%AF%E7%A7%AF%20%E2%88%92h(v)%22%5D%0A%20%20V%20--%3E%20SUM%5B%22%E6%80%BB%E5%A2%9E%E9%87%8F%20%3D%20%2Bh(u)%E2%88%92h(v)%EF%BC%8C%E4%B8%8E%E8%B5%B0%E6%B3%95%E6%97%A0%E5%85%B3%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=l('<p>空间仍可 \\(O(V^2)\\) 存答案；算法的时间优势在 \\(E=o(V^2/\\log V)\\) 一类稀疏。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写费用流、不加速动态边权。负环上「最短」无定义。后课最小生成树换成无向边权和，不是点对距离。后课默认：稀疏一般权全源用 Johnson；稠密用 Floyd。</p><p><span class="marginnote">直觉类比：势 h 像给每个城市标「海拔修正」——权重里扣掉海拔差，剩下的全是平地开销；只要修正量来自同一张海拔表（超源 BF），任何路线的修正总额只看起点和终点。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>势把一般权变成非负，最短路径集不变。</li><li>一次 BF + \\(V\\) 次 Dijkstra；负环在 BF 处拒绝。</li><li>稠密仍 Floyd。</li><li>出处：Johnson, 1977；CLRS 第 25.3 节。</li></ul>',6))])}const w=d(B,[["render",u]]);export{v as __pageData,w as default};
